// Normaliza os dados do gateway (Mercado Pago, Stripe ou Kiwify/Hotmart)
// e assegura que é um pagamento único sem cobrança recorrente.
const body = $input.item.json.body || $input.item.json;

const phone = body.phone_number || body.customer_phone || (body.payer && body.payer.phone && body.payer.phone.number) || '';
const paymentId = body.id || body.payment_id || body.data?.id || 'PAY_' + Date.now();
const amount = body.transaction_amount || body.amount || 0;
const customerName = body.customer_name || (body.payer && body.payer.first_name) || 'Cliente';

// Garante que é pagamento único (is_recurring: false)
return {
  json: {
    phone_number: phone,
    payment_id: String(paymentId),
    amount: Number(amount),
    customer_name: customerName,
    provider: body.provider || 'mercadopago',
    is_recurring: false
  }
};

